package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaUzDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("Allohumma Bika Asbahna", "Allohim, sening haqing bilan tongga kiramiz va sening haqing bilan shomga kiramiz. Sening haqing bilan yashaymiz va Sen bilan o'lamiz va qayta tirilish Sengadir.", "Ertalabda.", "Payg'ambar ﷺ sahobalarga ertalab va kechqurun aytishni o'rgatgan."),
        "dua_allahumma_bika_amsayna" to DuaText("Allohumma Bika Amsayna", "Allohim, sen haqing bilan shomga kiramiz va tongga kiramiz. Sen bilan yashaymiz va Sen bilan o'lamiz va qaytish Sengadir.", "Kechqurun.", "Payg'ambar ﷺ sahobalarga ertalab va kechqurun aytishni o'rgatgan."),
        "dua_afiyah_morning" to DuaText("Afiyani so'rash", "Allohim, sendan dunyo va oxiratda mag'firat va saodat so'rayman.", "Payg'ambarimiz ﷺ ertalab ham, kechqurun ham bu duoni tark etmadilar.", "Hech kimga farovonlikdan yaxshiroq narsa berilmagan."),
        "dua_afini_fi_badani" to DuaText("Tananing salomatligi, eshitish va ko'rish", "Allohim, vujudimga omonlik ber. Allohim, qulog'imga omonlik ber. Allohim, ko'zlarimga omonlik ber. Sendan boshqa iloh yo'q.", "Har kuni ertalab va kechqurun uch marta.", "Salomatlik va hislarni himoya qilish uchun duo."),
        "dua_ya_hayyu_aslih" to DuaText("Mening barcha ishlarimni to'g'irlang", "Ey barhayot, ey Parvardigor, rahmating ila madad so‘rayman: barcha ishlarimni to‘g‘rilagin va ko‘z ochib yumguncha ham meni o‘z holimga qo‘yma.", "Payg'ambarimiz ﷺ Fotimaga (RA) ertalab va kechqurun aytishni tavsiya qilganlar.", "Har bir ishda Allohdan yordam so'rash."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Juvayriya tasbehi (RA)", "Alloh taologa pokdir va hamma hamd Unga bo'lsin - yaratganlari qanchalar, O'zi rozi bo'lganlaricha, Arshining og'irligi va so'zining siyohiga tengdir.", "Ertalab uch marta - soatlab zikr qilishdan og'irroq.", "Bu to'rtta jumlani uch marta aytish tong sahardan yarim tonggacha zikrdan ustundir."),
        "dua_salawat" to DuaText("Durud-i-Ibrohimiy", "Allohim, Ibrohim alayhissalomga (AS) va Ibrohim alayhissalomga salovot yuborganing kabi Muhammad ﷺ va Muhammad alayhissalomga ham salomlar yubor. Sen maqtovli, ulug'vorsan. Allohim, Ibrohimga (AS) va Ibrohimning oilasiga baraka berganing kabi Muhammadga ﷺ va Muhammadning oilasiga salom ber. Sen maqtovli, ulug'vorsan.", "Namozda va har doim Payg'ambarga salovot ﷺ.", "Kim bir marta salovot aytsa, Alloh unga o'nta rahmat aytadi (Muslim 408)."),
        "dua_wudu_after" to DuaText("Tahoratdan keyin", "Guvohlik beramanki, Allohdan boshqa hech kim ibodat qilinishga loyiq emas, yolg'iz, sherigi yo'q va Muhammad ﷺ Uning bandasi va rasulidir. Allohim, meni tavba qiluvchilar va poklanuvchilardan qilgin.", "Tahorat olgach.", "Jannatning sakkiz eshigi ochilib, xohlaganidan kirishi mumkin."),
        "dua_wudu_before" to DuaText("Tahorat oldidan", "Alloh nomi bilan.", "Tahorat boshlaganda.", "Allohning ismini zikr qilmagan kishi uchun tahorat yo'q."),
        "dua_istiftah" to DuaText("Ochilish duosi (Sana)", "Allohim senga pok va hamdu sanolar bo'lsin. Sening isming muborakdir, ulug'liging ulug'dir va Sendan boshqa iloh yo'qdir.", "Namoz boshida, ochilgan takbirdan keyin.", "Namozning sunnat ochilish duosi."),
        "dua_ruku" to DuaText("Rukuda", "Ulug‘ Robbim pokdir.", "Rukuda kamida uch marta.", "Rukuning sunnat tasbihi."),
        "dua_sujood" to DuaText("Sujudda", "Ulug‘ Robbim pok bo‘lsin.", "Sujudda kamida uch marta.", "Qul sajdada Robbisiga eng yaqindir (Muslim 482)."),
        "dua_rising_ruku" to DuaText("Rukudan ko'tarilish", "Alloh taolo Unga hamd aytayotganni eshitadi. Ey Robbimiz, Senga hamd bo'lsin.", "Rukudan turib, tik turgan holda.", "Kimning “Rabbana va lakal-hamd”i farishtalarnikiga to‘g‘ri kelsa, uning o‘tgan gunohlari kechiriladi."),
        "dua_between_sajdas" to DuaText("Ikki sajda orasi", "Rabbim, meni kechir. Rabbim, meni kechir.", "Ikki sajda orasida o‘tirgan holda.", "Sajdalar orasidagi o'tirishning sunnat duosi."),
        "dua_before_salam_four" to DuaText("To'rt narsadan panoh (Salomdan oldin)", "Allohim, do'zax azobidan, qabr azobidan, hayot va o'lim fitnasidan va Soxta Masih (Dajjol) fitnasining yomonligidan Sendan panoh so'rayman.", "Yakuniy tashahhud va salovotdan keyin, salom oldidan.", "Payg'ambarimiz ﷺ mana shu to'rt narsadan panoh so'rashni buyurdilar."),
        "dua_qunoot_witr" to DuaText("Vitrda qunut", "Allohim, meni hidoyat qilgan zotlaring qatorida hidoyat qil, omonlik ato etgan zotlaring qatorida meni ham omonlik qil, o‘z panohida bo‘lganlaring qatorida meni o‘z panohiga ol, bergan narsamga barakot ber va hukm qilgan narsangning yomonligidan saqlagin. Sen hukm qilursan va hech kim Senga hukm qilmaydi. Rabbimiz, Sen barakotli va poksan.", "Vitr namozida - Payg'ambar ﷺ Hasan ibn Aliga o'rgatgan (RA).", "Vitrning sunnat qunuti. (Hanafiylar orasida “Allohumma inna nasta’inuka” ham mashhurdir.)"),
        "dua_qunoot_hanafi" to DuaText("Qunut (Allohumma Inna Nasta'inuka)", "Allohim, Sendan madad va mag'firat so'raymiz, Senga iymon keltiramiz va Senga tavakkul qilamiz, Senga hamd aytamiz, Senga shukr qilamiz va noshukr bo'lmaymiz, kim senga osiy bo'lsa, uni tark qilamiz. Allohim, Sengagina ibodat qilamiz, Senga ibodat qilamiz va sajda qilamiz, Senga shoshilamiz va jihod qilamiz, Sening rahmatingdan umidvormiz va azobingdan qo'rqamiz. Albatta, azobing kofirlarga yetib borur.", "Vitrda — hanafiylarning amali.", "Umardan (RA) qunutda rivoyat qilingan."),
        "dua_sleep_aslamtu" to DuaText("Uyqudan oldin oxirgi so'zlar", "Allohim, men Sendan umidvor va sendan qo‘rqib, o‘zingga bo‘ysundim, ishimni Senga topshirdim va Sening panohingga bel bog‘ladim. Sendan boshqa panoh va qochish yo'q. Men nozil qilgan kitobingga va sen yuborgan payg‘ambaringga iymon keltirdim.", "Tahoratdan so'ng, o'ng tomonda yotish - uyqu oldidan oxirgi so'zlar.", "Agar o'sha kechada vafot etsa, fitrat (islom) bilan vafot etadi."),
        "dua_waking_night" to DuaText("Kechasi uyg'onish", "Allohdan boshqa hech kim ibodat qilinishga loyiq emas, U yolg'izdir, sherigi yo'q. Hukmronlik Unikidir, hamd Unikidir va U har narsaga qodirdir. Barcha hamd Allohga xosdir, Alloh pokdir, Allohdan boshqa hech kim ibodat qilinishga loyiq emas, Alloh eng buyukdir. Kuch va quvvat faqat Allohning yordami bilandir. Allohim, meni kechir.", "Kechasi uyg'onganda.", "Duosi ijobat bo'ladi, tahorat olib, namoz o'qisa, duosi qabul bo'ladi."),
        "dua_hamm_ibn_masud" to DuaText("G'am uchun duo (Ibn Mas'ud)", "Allohim, men sening bandang, bandangning o‘g‘liman, cho‘ringning o‘g‘liman. Peshonam Sening qo'lingda, Menga bo'lgan amring bajo bo'ldi va men haqimda hukming adolatlidir. O'zingga tegishli bo'lgan, O'zingga nom qo'ygan yoki kitobingda nozil qilgan yoki biron bir maxluqotga o'rgatgan yoki g'ayb ilmida o'zingda saqlagan har bir ism bilan Sendan so'rayman - Qur'onni qalbimning bahori, ko'ksimning nuri, g'amimning ketkazuvchanligi va tashvishlarimning ketishini.", "G'am va qayg'uda - Alloh qayg'uni quvonch bilan almashtiradi.", "Alloh uning tashvish va g'amini ketkazadi va uning o'rniga quvonch beradi."),
        "dua_difficulty_sahl" to DuaText("Biror narsa qiyin bo'lganda", "Allohim, sen oson qilgan narsadan boshqa narsa oson emas, agar xohlasang, qiyinni ham oson qilursan.", "Biror narsa qiyin bo'lganda.", "Imtihonlarda qulaylik va qiyin vazifalar."),
        "dua_musibah" to DuaText("Falokatda (Istirja)", "Biz Allohnikimiz va Unga qaytguvchimiz. Allohim, musibatimga ajr bergin va uning o‘rnini yaxshisi bilan almashtir.", "Har qanday yo'qotish yoki falokatda.", "Alloh, albatta, yaxshiroq narsani beradi - Ummu Salama (RA) Rasulullohga ﷺ berilgan."),
        "dua_debt" to DuaText("Qarzdan qutulish uchun", "Allohim, harom qilgan narsangni halol qilganing bilan menga kifoya qil va fazlung ila meni O‘zingdan boshqa hamma narsadan mustaqil qilgin.", "Qarzni to'lash uchun - Ali tomonidan o'rgatilgan (RA).", "Qarz tog'dek bo'lsa ham, Alloh uni to'ldiradi."),
        "dua_anger" to DuaText("G'azablanganda", "Men la’nati shaytondan Allohdan panoh tilayman.", "G'azablanganda.", "Rasululloh sollallohu alayhi vasallam ﷺ dedilar: Agar shunday desa, g'azabi ketadi."),
        "dua_waswasa" to DuaText("Imonda Vasvasaga qarshi", "Men Allohga va Uning payg'ambarlariga ishonaman.", "Qachonki iymon haqida shaytoniy shivirlar keladi.", "Pichir kelganda, shu gapni ayting va shu yerda to'xtang (shuningdek, Allohdan panoh so'rang)."),
        "dua_travel_full" to DuaText("To'liq sayohat iltijosi", "Allohim, bu safarda sendan yaxshilik va taqvo va Oʻzing rozi boʻladigan amallarni soʻraymiz. Allohim, bu safarni bizga oson qil va uning masofasini qisqartir. Allohim, sen safarda hamrohsan va oilaning valiysan.", "Safarga chiqayotganda, “Subhanalladhi sakhkhara”dan keyin.", "To'liq sunnat sayohat duosi."),
        "dua_return_travel" to DuaText("Sayohatdan qaytish", "Qaytib, tavba qilib, Parvardigorimizga sajda qilib, hamd aytayapmiz.", "Safardan qaytayotganda.", "Payg'ambarimiz ﷺ safardan qaytayotganlarida aytdilar."),
        "dua_farewell_traveller" to DuaText("Sayohatchi bilan xayrlashish", "Diningizni, omonatingizni va amallaringiz oqibatini Allohga topshirdim.", "Sayohatchi bilan xayrlashayotganda.", "Allohga omonat qilingan narsa hech qachon yo'qolmaydi."),
        "dua_entering_town" to DuaText("Bir joyda to'xtash", "Alloh taoloning komil kalimalari bilan yaratgan barcha narsalarining yomonligidan panoh tilayman.", "Bir joyda to'xtash yoki yangi shaharga kelganda.", "U yerdan ketguncha unga hech narsa zarar yetkaza olmaydi."),
        "dua_boarding_ship" to DuaText("Kema/avtomobilga chiqish", "Uning suzib yurishi va langar qoldirishi Allohning nomi bilandir. Albatta, Robbim mag'firatli va rahmlidir.", "Kema yoki transport vositasiga chiqishda - Nuh payg'ambarning so'zlari (AS).", "Qur'on oyati - Nuhning (AS) kemasining duosi."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Hayyul-Qayyum bilan istig'for", "O'zidan o'zga iloh yo'q, barhayot va rizq beruvchi Allohdan mag'firat so'rayman va Unga tavba qilaman.", "Tavba qilish uchun.", "Jang maydonidan qochgan bo'lsa ham gunohlari kechiriladi."),
        "dua_rabbighfir_warham" to DuaText("Rabbigfir Uorxem", "Robbim, kechir va rahm qil, chunki Sen rahm qiluvchilarning eng yaxshisisan.", "Qur'on duosi - kechirim va rahm-shafqat uchun.", "Mo'minun surasining oxirgi oyati."),
        "dua_majlis_kaffarah" to DuaText("Kafforat al-Majlis", "Allohim senga pok va hamdu sanolar bo'lsin. Sendan o'zga iloh yo'qligiga guvohlik beraman. Sendan mag'firat so'rayman va Senga tavba qilaman.", "Yig'ilishdan turganda.", "Bu majlisda aytilgan har qanday noto'g'ri gapga kafforat bo'ladi."),
        "dua_jami_forgiveness" to DuaText("Keng qamrovli kechirim", "Allohim, xatolarimni, bilimsizligimni, ishlarimdagi ortiqchaligimni va mendan ham yaxshi bilgan narsamni kechirgin.", "Payg'ambarning to'liq duosi ﷺ.", "Rasululloh ﷺ bu duoni qilardilar."),
        "dua_parents_nuh" to DuaText("Ota-onalar uchun Nuh duosi (AS)", "Parvardigorim, meni, ota-onamni, uyimga mo‘min bo‘lib kirganlarni, barcha mo‘min erkaklar va mo‘mina ayollarni mag‘firat et.", "Ota-ona va mo'minlar uchun.", "Nuh payg'ambarning duosi (AS)."),
        "dua_shukr_parents" to DuaText("Ota-onalar va solih avlodlar uchun minnatdorchilik", "Parvardigorim, menga va ota-onamga bergan ne’matingga shukr qilishimni, O‘zing rozi bo‘ladigan solih amallarimni qilishimni va zurriyotimni solihlardan qilgin. Senga tavba qilib, tavba qilganlardanman.", "Qur'onda qirq yoshga to'lish duosi.", "Minnatdorchilik, yaxshi ishlar va farzandlarining solihligi - barchasi bitta duoda."),
        "dua_intimacy" to DuaText("Oilaviy munosabatlardan oldin", "Alloh nomi bilan. Allohim, shaytonni bizdan uzoq qil va shaytonni sen bizga bergan (farzandlar)ingdan uzoq qil.", "Nikoh munosabatlaridan oldin.", "Farzandga hukm qilinsa, shayton unga hech qachon zarar yetkazmaydi."),
        "dua_ibrahim_children_protection" to DuaText("Uy va bolalarni himoya qilish", "Parvardigorim, bu shaharni xavfsiz qilgin va meni va bolalarimni butlarga ibodat qilishdan saqla.", "Ibrohim payg'ambarning duosi (AS) - shahar va uning bolalari xavfsizligi uchun.", "Tavhidda mustahkam turish uchun duo."),
        "dua_drinking_milk" to DuaText("Sut ichganda", "Allohim, uni bizga barakali qil va undan ziyoda qilgin.", "Sut ichganda.", "Sut ham oziq-ovqat, ham ichimlik sifatida etarli."),
        "dua_iftar_host" to DuaText("Boshqalar bilan iftorlik qilganda", "Ro‘zadorlar siz bilan iftor qilsin, rizqingizni solihlar yesin, farishtalar duo qilsin.", "Birovning uyida iftorlik qilganda.", "Payg'ambarimizning mezbon uchun ﷺ duosi."),
    )
}
